<script setup>const { public:{appName} }=useRuntimeConfig(); const route=useRoute(); const {data:me}=await useFetch('/api/auth/me'); async function logout(){await $fetch('/api/auth/logout',{method:'POST'});navigateTo('/login')}</script>
<template><div class="min-h-screen paper"><header v-if="me?.user" class="bg-slate-950 text-white px-6 py-4 flex items-center justify-between"><NuxtLink to="/" class="font-black text-xl">{{appName}}</NuxtLink><nav class="flex gap-4 items-center"><NuxtLink to="/">Dashboard</NuxtLink><NuxtLink v-if="me.user.role==='admin'" to="/admin">Admin</NuxtLink><span class="text-sm opacity-70">{{me.user.name}} · {{me.user.role}}</span><button class="btn bg-white/10" @click="logout">Keluar</button></nav></header><NuxtPage /></div></template>